import torch


def gen_inputs(ctx, device):
    shape = ctx["A__shape"]
    dtype = getattr(torch, ctx["A__dtype"])
    n = shape[-1]
    a = torch.randn(shape, dtype=dtype, device=device)
    # Symmetric positive definite input avoids singular LDL cases.
    A = a @ a.mT + torch.eye(n, dtype=dtype, device=device) * 0.1
    return {"A": A}


def run(A):
    return torch.linalg.ldl_factor_ex(A)
